package ae.pk;

import static org.junit.jupiter.api.Assertions.*;

import java.math.BigInteger;
import java.security.AlgorithmParameters;
import java.security.spec.ECGenParameterSpec;
import java.security.spec.ECParameterSpec;
import java.util.Random;
import org.junit.jupiter.api.Test;

class CurveTest {
    private static BigInteger h(String s) { return new BigInteger(s.replace(" ", ""), 16); }

    /** Naive affine oracle: textbook formulas with modInverse, double-and-add. */
    static Point naiveAdd(Curve c, Point p, Point q) {
        if (p.isInfinity()) return q;
        if (q.isInfinity()) return p;
        BigInteger m;
        if (p.x().equals(q.x())) {
            if (!p.y().equals(q.y()) || p.y().signum() == 0) return Point.INFINITY;
            m = p.x().pow(2).multiply(BigInteger.valueOf(3)).add(c.a())
                .multiply(p.y().shiftLeft(1).modInverse(c.p())).mod(c.p());
        } else {
            m = q.y().subtract(p.y()).multiply(q.x().subtract(p.x()).mod(c.p()).modInverse(c.p())).mod(c.p());
        }
        BigInteger x = m.pow(2).subtract(p.x()).subtract(q.x()).mod(c.p());
        BigInteger y = m.multiply(p.x().subtract(x)).subtract(p.y()).mod(c.p());
        return new Point(x, y);
    }

    static Point naiveMul(Curve c, BigInteger k, Point p) {
        Point r = Point.INFINITY;
        for (int i = k.bitLength() - 1; i >= 0; i--) {
            r = naiveAdd(c, r, r);
            if (k.testBit(i)) r = naiveAdd(c, r, p);
        }
        return r;
    }

    @Test
    void p256ConstantsMatchJdk() throws Exception {
        AlgorithmParameters ap = AlgorithmParameters.getInstance("EC");
        ap.init(new ECGenParameterSpec("secp256r1"));
        ECParameterSpec jdk = ap.getParameterSpec(ECParameterSpec.class);
        Curve c = Curve.P256;
        assertEquals(((java.security.spec.ECFieldFp) jdk.getCurve().getField()).getP(), c.p());
        assertEquals(jdk.getCurve().getA(), c.a().mod(c.p()));
        assertEquals(jdk.getCurve().getB(), c.b());
        assertEquals(jdk.getOrder(), c.n());
        assertEquals(jdk.getGenerator().getAffineX(), c.g().x());
        assertEquals(jdk.getGenerator().getAffineY(), c.g().y());
        assertEquals(1, jdk.getCofactor());
    }

    @Test
    void generatorsAreOnCurveAndHaveOrderN() {
        for (Curve c : new Curve[] {Curve.P256, Curve.SECP256K1}) {
            assertTrue(c.onCurve(c.g().x(), c.g().y()), c.name());
            assertTrue(c.mul(c.n(), c.g()).isInfinity(), c.name() + " n*G");
            Point nm1 = c.mul(c.n().subtract(BigInteger.ONE), c.g());
            assertEquals(c.g().x(), nm1.x(), c.name());
            assertEquals(c.p().subtract(c.g().y()), nm1.y(), c.name() + " (n-1)G = -G");
            assertTrue(c.mul(BigInteger.ZERO, c.g()).isInfinity());
            assertEquals(c.g(), c.mul(BigInteger.ONE, c.g()));
        }
    }

    @Test
    void publishedDoubleOfGenerator() {
        Point p2 = Curve.P256.mul(BigInteger.TWO, Curve.P256.g());
        assertEquals(h("7CF27B18 8D034F7E 8A523803 04B51AC3 C08969E2 77F21B35 A60B48FC 47669978"), p2.x());
        assertEquals(h("07775510 DB8ED040 293D9AC6 9F7430DB BA7DADE6 3CE98229 9E04B79D 227873D1"), p2.y());
        Point k2 = Curve.SECP256K1.mul(BigInteger.TWO, Curve.SECP256K1.g());
        assertEquals(h("C6047F94 41ED7D6D 3045406E 95C07CD8 5C778E4B 8CEF3CA7 ABAC09B9 5C709EE5"), k2.x());
    }

    @Test
    void jacobianMatchesNaiveOracleOnRandomScalars() {
        Random rnd = new Random(7);
        for (Curve c : new Curve[] {Curve.P256, Curve.SECP256K1}) {
            for (int i = 0; i < 12; i++) {
                BigInteger k = new BigInteger(1 + rnd.nextInt(256), rnd);
                assertEquals(naiveMul(c, k, c.g()), c.mul(k, c.g()), c.name() + " k=" + k.toString(16));
            }
        }
    }

    @Test
    void scalarMultiplicationIsHomomorphic() {
        Random rnd = new Random(11);
        for (Curve c : new Curve[] {Curve.P256, Curve.SECP256K1}) {
            BigInteger a = new BigInteger(255, rnd).add(BigInteger.ONE);
            BigInteger b = new BigInteger(255, rnd).add(BigInteger.ONE);
            Point pa = c.mul(a, c.g());
            Point pb = c.mul(b, c.g());
            assertEquals(c.mul(a.add(b), c.g()), c.add(pa, pb));
            assertEquals(c.mul(a.multiply(b).mod(c.n()), c.g()), c.mul(b, pa));
            assertEquals(c.add(pa, pb), c.add(pb, pa));
            assertEquals(c.mul(a.add(b), c.g()), c.mulAdd(a, c.g(), b, c.g()));
            assertEquals(c.add(c.mul(a, c.g()), c.mul(b, pb)), c.mulAdd(a, c.g(), b, pb));
        }
    }

    @Test
    void addEdgeCases() {
        Curve c = Curve.P256;
        Point g = c.g();
        Point negG = new Point(g.x(), c.p().subtract(g.y()));
        assertTrue(c.add(g, negG).isInfinity(), "P + (-P)");
        assertEquals(c.mul(BigInteger.TWO, g), c.add(g, g), "P + P doubles");
        assertEquals(g, c.add(g, Point.INFINITY));
        assertEquals(g, c.add(Point.INFINITY, g));
        assertTrue(c.add(Point.INFINITY, Point.INFINITY).isInfinity());
        // G + 2G + (-3G) = O exercises mixed Jacobian paths
        Point g2 = c.mul(BigInteger.TWO, g);
        Point g3 = c.add(g2, g);
        assertEquals(c.mul(BigInteger.valueOf(3), g), g3);
        assertTrue(c.add(c.add(g, g2), new Point(g3.x(), c.p().subtract(g3.y()))).isInfinity());
    }

    @Test
    void encodeDecodeRoundTrip() {
        Random rnd = new Random(5);
        for (Curve c : new Curve[] {Curve.P256, Curve.SECP256K1}) {
            for (int i = 0; i < 6; i++) {
                Point p = c.mul(new BigInteger(250, rnd).add(BigInteger.ONE), c.g());
                byte[] u = c.encode(p, false);
                byte[] z = c.encode(p, true);
                assertEquals(65, u.length);
                assertEquals(33, z.length);
                assertEquals(4, u[0]);
                assertEquals(p.y().testBit(0) ? 3 : 2, z[0]);
                assertEquals(p, c.decode(u));
                assertEquals(p, c.decode(z));
            }
        }
    }

    @Test
    void decodeRejectsMalformedPoints() {
        Curve c = Curve.P256;
        byte[] good = c.encode(c.g(), false);
        assertEquals(c.g(), c.decode(good), "control");
        assertThrows(IllegalArgumentException.class, () -> c.decode(new byte[0]));
        assertThrows(IllegalArgumentException.class, () -> c.decode(new byte[] {0}), "infinity is not a key");
        byte[] badPrefix = good.clone();
        badPrefix[0] = 5;
        assertThrows(IllegalArgumentException.class, () -> c.decode(badPrefix));
        byte[] hybrid = good.clone();
        hybrid[0] = (byte) (6 + (c.g().y().testBit(0) ? 1 : 0));
        assertThrows(IllegalArgumentException.class, () -> c.decode(hybrid));
        assertThrows(IllegalArgumentException.class, () -> c.decode(java.util.Arrays.copyOf(good, 64)));
        assertThrows(IllegalArgumentException.class, () -> c.decode(java.util.Arrays.copyOf(good, 66)));
        byte[] offCurve = good.clone();
        offCurve[64] ^= 1; // y changes by one: no longer on curve
        assertThrows(IllegalArgumentException.class, () -> c.decode(offCurve));
    }

    @Test
    void decodeRejectsNonCanonicalCoordinates() {
        Curve c = Curve.SECP256K1; // p = 2^256 - 2^32 - 977, so small x + p still fits in 32 bytes
        BigInteger x = BigInteger.valueOf(1);
        // find a small x on the curve: rhs must be a QR; scan
        BigInteger px = null;
        BigInteger py = null;
        for (long t = 1; t < 200 && px == null; t++) {
            BigInteger xx = BigInteger.valueOf(t);
            BigInteger rhs = xx.pow(3).add(c.b()).mod(c.p());
            if (rhs.modPow(c.p().subtract(BigInteger.ONE).shiftRight(1), c.p()).equals(BigInteger.ONE)) {
                px = xx;
                py = rhs.modPow(c.p().add(BigInteger.ONE).shiftRight(2), c.p());
            }
        }
        assertNotNull(px);
        Point p = new Point(px, py);
        assertEquals(p, c.decode(c.encode(p, false)), "control");
        byte[] aliasX = new byte[65];
        aliasX[0] = 4;
        System.arraycopy(Curve.i2osp(px.add(c.p()), 32), 0, aliasX, 1, 32);
        System.arraycopy(Curve.i2osp(py, 32), 0, aliasX, 33, 32);
        assertThrows(IllegalArgumentException.class, () -> c.decode(aliasX), "x >= p");
        byte[] comp = c.encode(p, true);
        System.arraycopy(Curve.i2osp(px.add(c.p()), 32), 0, comp, 1, 32);
        assertThrows(IllegalArgumentException.class, () -> c.decode(comp), "compressed x >= p");
    }

    @Test
    void compressedXWithoutSquareRootIsRejected() {
        Curve c = Curve.P256;
        BigInteger half = c.p().subtract(BigInteger.ONE).shiftRight(1);
        int rejected = 0;
        int accepted = 0;
        for (long t = 1; t <= 30; t++) {
            BigInteger x = BigInteger.valueOf(t);
            BigInteger rhs = x.pow(3).add(c.a().multiply(x)).add(c.b()).mod(c.p());
            boolean residue = rhs.modPow(half, c.p()).equals(BigInteger.ONE);
            byte[] enc = new byte[33];
            enc[0] = 2;
            System.arraycopy(Curve.i2osp(x, 32), 0, enc, 1, 32);
            if (residue) {
                Point p = c.decode(enc);
                assertTrue(c.onCurve(p.x(), p.y()));
                assertFalse(p.y().testBit(0), "prefix 02 means even y");
                accepted++;
            } else {
                assertThrows(IllegalArgumentException.class, () -> c.decode(enc), "x=" + x);
                rejected++;
            }
        }
        assertTrue(rejected >= 5 && accepted >= 5, "mix " + rejected + "/" + accepted);
    }
}

tests.src/test/java/ae/pk/ToyCurveTest.java:
package ae.pk;

import static org.junit.jupiter.api.Assertions.*;

import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;

/** A tiny curve found by brute force makes nonce-retry and degenerate-signature paths reachable. */
class ToyCurveTest {
    static final int P = 103; // 103 = 3 mod 4
    static final Curve TOY = findToyCurve();

    private static Curve findToyCurve() {
        for (int a = 1; a < P; a++) {
            for (int b = 1; b < P; b++) {
                if ((4 * a * a * a + 27 * b * b) % P == 0) continue; // singular
                if (BigInteger.valueOf(b).modPow(BigInteger.valueOf((P - 1) / 2), BigInteger.valueOf(P)).intValue() != 1) continue; // want a point with x = 0
                List<int[]> pts = new ArrayList<>();
                for (int x = 0; x < P; x++) {
                    for (int y = 0; y < P; y++) {
                        if ((y * y - (x * x * x + a * x + b)) % P == 0) pts.add(new int[] {x, y});
                    }
                }
                int order = pts.size() + 1; // plus infinity
                if (BigInteger.valueOf(order).isProbablePrime(30) && order > 60) {
                    int[] g = pts.get(0);
                    return new Curve("toy", BigInteger.valueOf(P), BigInteger.valueOf(a), BigInteger.valueOf(b),
                        BigInteger.valueOf(order), BigInteger.valueOf(g[0]), BigInteger.valueOf(g[1]));
                }
            }
        }
        throw new AssertionError("no toy curve");
    }

    @Test
    void curveConstructorValidates() {
        assertTrue(TOY.n().intValue() > 60);
        assertThrows(IllegalArgumentException.class, () -> new Curve("bad", TOY.p(), TOY.a(), TOY.b(),
            TOY.n().add(BigInteger.ONE), TOY.g().x(), TOY.g().y()), "wrong order");
        assertThrows(IllegalArgumentException.class, () -> new Curve("bad", TOY.p(), TOY.a(), TOY.b(),
            TOY.n(), TOY.g().x(), TOY.g().y().add(BigInteger.ONE)), "G off curve");
        assertThrows(IllegalArgumentException.class, () -> new Curve("bad", BigInteger.valueOf(101), TOY.a(), TOY.b(),
            TOY.n(), TOY.g().x(), TOY.g().y()), "p = 1 mod 4");
    }

    @Test
    void everyScalarMatchesNaiveOracleAndEncodingRoundTrips() {
        Point acc = Point.INFINITY;
        for (int k = 0; k <= TOY.n().intValue(); k++) {
            Point m = TOY.mul(BigInteger.valueOf(k), TOY.g());
            assertEquals(acc, m, "k=" + k);
            assertEquals(CurveTest.naiveMul(TOY, BigInteger.valueOf(k), TOY.g()), m);
            if (!m.isInfinity()) {
                assertEquals(m, TOY.decode(TOY.encode(m, true)), "compressed k=" + k);
                assertEquals(m, TOY.decode(TOY.encode(m, false)), "uncompressed k=" + k);
            }
            acc = CurveTest.naiveAdd(TOY, acc, TOY.g());
        }
        assertEquals(TOY.g(), acc, "after n+1 additions the naive accumulator is (n+1)G = G");
    }

    @Test
    void signVerifyForEveryKeyAndManyHashesIncludingRetries() throws Exception {
        int n = TOY.n().intValue();
        int rejectedNonces = 0;
        int signatures = 0;
        int wrongKeyAccepted = 0;
        for (int d = 1; d < n; d++) {
            Point q = Ecdsa.publicKey(TOY, BigInteger.valueOf(d));
            for (int i = 0; i < 12; i++) {
                byte[] hash = EcdsaTest.sha("k" + d + "/" + i);
                Ecdsa.Signature sig = Ecdsa.sign(TOY, BigInteger.valueOf(d), hash);
                assertTrue(Ecdsa.verify(TOY, q, hash, sig), "d=" + d + " i=" + i);
                BigInteger k = Ecdsa.nonce(TOY, BigInteger.valueOf(d), hash);
                assertTrue(k.signum() > 0 && k.compareTo(TOY.n()) < 0);
                signatures++;
                // the nonce the signature actually used differs from the first candidate when a retry happened
                BigInteger r1 = TOY.mul(k, TOY.g()).x().mod(TOY.n());
                if (!r1.equals(sig.r())) rejectedNonces++;
                int other = d % (n - 1) + 1; // a different key; on a ~100-element group ~1/n of wrong keys still verify
                if (Ecdsa.verify(TOY, Ecdsa.publicKey(TOY, BigInteger.valueOf(other)), hash, sig)) wrongKeyAccepted++;
            }
        }
        assertTrue(wrongKeyAccepted < signatures / 10, "wrong-key accepts " + wrongKeyAccepted + "/" + signatures);
        assertTrue(rejectedNonces > 0, "retry path exercised (" + rejectedNonces + "/" + signatures + ")");
    }

    @Test
    void nonCanonicalCoordinatesAreRejectedAtTheBoundary() {
        // fieldBytes = 1, so every byte value 0..255 is encodable; only 0..102 are canonical
        assertEquals(1, TOY.fieldBytes());
        BigInteger half = BigInteger.valueOf((P - 1) / 2);
        int canonicalAccepted = 0;
        for (int x = 0; x < 256; x++) {
            BigInteger rhs = BigInteger.valueOf(x).pow(3).add(TOY.a().multiply(BigInteger.valueOf(x))).add(TOY.b()).mod(TOY.p());
            boolean residue = rhs.signum() == 0 || rhs.modPow(half, TOY.p()).equals(BigInteger.ONE);
            for (int prefix = 2; prefix <= 3; prefix++) {
                byte[] enc = {(byte) prefix, (byte) x};
                if (x < P && residue && !(rhs.signum() == 0 && prefix == 3)) {
                    assertEquals(prefix == 3, TOY.decode(enc).y().testBit(0), "x=" + x);
                    canonicalAccepted++;
                } else {
                    final int fx = x;
                    assertThrows(IllegalArgumentException.class, () -> TOY.decode(enc), "x=" + fx + " prefix=" + prefix);
                }
            }
        }
        assertTrue(canonicalAccepted > 100, "accepted " + canonicalAccepted);
    }

    @Test
    void uncompressedCoordinatesAtLeastPAreRejected() {
        int checkedAliases = 0;
        for (int k = 1; k < TOY.n().intValue(); k++) {
            Point m = TOY.mul(BigInteger.valueOf(k), TOY.g());
            int x = m.x().intValue();
            int y = m.y().intValue();
            assertEquals(m, TOY.decode(new byte[] {4, (byte) x, (byte) y}), "control k=" + k);
            if (y + P < 256) {
                assertThrows(IllegalArgumentException.class, () -> TOY.decode(new byte[] {4, (byte) x, (byte) (y + P)}), "y alias");
                checkedAliases++;
            }
            if (x + P < 256) {
                assertThrows(IllegalArgumentException.class, () -> TOY.decode(new byte[] {4, (byte) (x + P), (byte) y}), "x alias");
                checkedAliases++;
            }
        }
        assertTrue(checkedAliases > 20, "aliases checked: " + checkedAliases);
    }
}

tests.src/test/java/ae/pk/PrimesTest.java:
package ae.pk;

import static org.junit.jupiter.api.Assertions.*;

import java.math.BigInteger;
import java.util.Random;
import org.junit.jupiter.api.Test;

class PrimesTest {
    @Test
    void agreesWithSieveBelow200000() {
        int limit = 200_000;
        boolean[] comp = new boolean[limit];
        comp[0] = true;
        comp[1] = true;
        for (int i = 2; (long) i * i < limit; i++) {
            if (!comp[i]) for (int j = i * i; j < limit; j += i) comp[j] = true;
        }
        Random rnd = new Random(1);
        int primes = 0;
        for (int n = 0; n < limit; n++) {
            assertEquals(!comp[n], Primes.isProbablePrime(BigInteger.valueOf(n), rnd), "n=" + n);
            if (!comp[n]) primes++;
        }
        assertEquals(17984, primes, "pi(200000)");
        assertFalse(Primes.isProbablePrime(BigInteger.valueOf(-7), rnd), "negative");
    }

    @Test
    void rejectsStrongPseudoprimesAndCarmichaelNumbers() {
        Random rnd = new Random(2);
        // strong pseudoprimes to base 2, Carmichael numbers, and the smallest spsp to bases 2,3,5,7
        long[] composites = {2047, 3277, 4033, 4681, 8321, 561, 1105, 41041, 825265, 321197185L,
            3215031751L, 3825123056546413051L};
        for (long c : composites) {
            assertFalse(Primes.isProbablePrime(BigInteger.valueOf(c), rnd), "composite " + c);
        }
        // 3317044064679887385961981 is a strong pseudoprime to the first 12 prime bases (3.3e24 bound is sharp)
        BigInteger sharp = new BigInteger("3317044064679887385961981");
        assertFalse(Primes.isProbablePrime(sharp, new Random(5)), "needs the random bases");
    }

    @Test
    void largePrimesAndComposites() {
        Random rnd = new Random(3);
        BigInteger m127 = BigInteger.ONE.shiftLeft(127).subtract(BigInteger.ONE);
        BigInteger m521 = BigInteger.ONE.shiftLeft(521).subtract(BigInteger.ONE);
        assertTrue(Primes.isProbablePrime(m127, rnd));
        assertTrue(Primes.isProbablePrime(m521, rnd));
        assertFalse(Primes.isProbablePrime(BigInteger.ONE.shiftLeft(67).subtract(BigInteger.ONE), rnd), "M67 composite");
        assertFalse(Primes.isProbablePrime(m127.multiply(m127), rnd), "square of a prime");
        assertFalse(Primes.isProbablePrime(m127.multiply(m521), rnd));
        assertTrue(Primes.isProbablePrime(Curve.P256.p(), rnd));
        assertTrue(Primes.isProbablePrime(Curve.P256.n(), rnd));
        assertTrue(Primes.isProbablePrime(Curve.SECP256K1.n(), rnd));
    }

    @Test
    void randomPrimeHasExactBitLengthTopBitsAndIsPrime() {
        Random rnd = new Random(9);
        for (int bits : new int[] {16, 64, 256}) {
            for (int i = 0; i < 5; i++) {
                BigInteger p = Primes.randomPrime(bits, rnd);
                assertEquals(bits, p.bitLength());
                assertTrue(p.testBit(bits - 2), "top two bits set so products have full length");
                assertTrue(p.isProbablePrime(40), "JDK oracle agrees " + p);
            }
        }
        assertEquals(Primes.randomPrime(128, new Random(4)), Primes.randomPrime(128, new Random(4)), "seeded");
        assertThrows(IllegalArgumentException.class, () -> Primes.randomPrime(3, new Random(1)));
    }
}

tests.src/test/java/ae/pk/EcdsaTest.java:
package ae.pk;

import static org.junit.jupiter.api.Assertions.*;

import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.security.AlgorithmParameters;
import java.security.KeyFactory;
import java.security.MessageDigest;
import java.security.PrivateKey;
import java.security.PublicKey;
import java.security.Signature;
import java.security.spec.ECGenParameterSpec;
import java.security.spec.ECParameterSpec;
import java.security.spec.ECPoint;
import java.security.spec.ECPrivateKeySpec;
import java.security.spec.ECPublicKeySpec;
import java.util.Random;
import javax.crypto.KeyAgreement;
import org.junit.jupiter.api.Test;

class EcdsaTest {
    static final Curve C = Curve.P256;
    static final BigInteger RFC_X = h("C9AFA9D8 45BA7516 6B5C2157 67B1D693 4E50C3DB 36E89B12 7B8A622B 120F6721");

    static BigInteger h(String s) { return new BigInteger(s.replace(" ", ""), 16); }

    static byte[] sha(String m) throws Exception {
        return MessageDigest.getInstance("SHA-256").digest(m.getBytes(StandardCharsets.UTF_8));
    }

    static ECParameterSpec jdkParams() throws Exception {
        AlgorithmParameters ap = AlgorithmParameters.getInstance("EC");
        ap.init(new ECGenParameterSpec("secp256r1"));
        return ap.getParameterSpec(ECParameterSpec.class);
    }

    static PublicKey jdkPub(Point q) throws Exception {
        return KeyFactory.getInstance("EC").generatePublic(new ECPublicKeySpec(new ECPoint(q.x(), q.y()), jdkParams()));
    }

    static PrivateKey jdkPriv(BigInteger d) throws Exception {
        return KeyFactory.getInstance("EC").generatePrivate(new ECPrivateKeySpec(d, jdkParams()));
    }

    @Test
    void rfc6979PublicKey() {
        Point q = Ecdsa.publicKey(C, RFC_X);
        assertEquals(h("60FED4BA 255A9D31 C961EB74 C6356D68 C049B892 3B61FA6C E669622E 60F29FB6"), q.x());
        assertEquals(h("7903FE10 08B8BC99 A41AE9E9 5628BC64 F2F1B20C 2D7E9F51 77A3C294 D4462299"), q.y());
    }

    @Test
    void rfc6979NonceVectors() throws Exception {
        assertEquals(h("A6E3C57D D01ABE90 08653839 8355DD4C 3B17AA87 3382B0F2 4D612949 3D8AAD60"),
            Ecdsa.nonce(C, RFC_X, sha("sample")));
        assertEquals(h("D16B6AE8 27F17175 E040871A 1C7EC350 0192C4C9 2677336E C2537ACA EE0008E0"),
            Ecdsa.nonce(C, RFC_X, sha("test")));
    }

    @Test
    void rfc6979SignatureVectors() throws Exception {
        Ecdsa.Signature s1 = Ecdsa.sign(C, RFC_X, sha("sample"));
        assertEquals(h("EFD48B2A ACB6A8FD 1140DD9C D45E81D6 9D2C877B 56AAF991 C34D0EA8 4EAF3716"), s1.r());
        assertEquals(h("F7CB1C94 2D657C41 D436C7A1 B6E29F65 F3E900DB B9AFF406 4DC4AB2F 843ACDA8"), s1.s());
        Ecdsa.Signature s2 = Ecdsa.sign(C, RFC_X, sha("test"));
        assertEquals(h("F1ABB023 518351CD 71D88156 7B1EA663 ED3EFCF6 C5132B35 4F28D3B0 B7D38367"), s2.r());
        assertEquals(h("019F4113 742A2B14 BD25926B 49C64915 5F267E60 D3814B4C 0CC84250 E46F0083"), s2.s());
    }

    @Test
    void signVerifyRoundTripBothCurves() throws Exception {
        Random rnd = new Random(3);
        for (Curve c : new Curve[] {Curve.P256, Curve.SECP256K1}) {
            for (int i = 0; i < 4; i++) {
                BigInteger d = new BigInteger(255, rnd).add(BigInteger.ONE);
                Point q = Ecdsa.publicKey(c, d);
                byte[] hash = sha("m" + i);
                Ecdsa.Signature sig = Ecdsa.sign(c, d, hash);
                assertTrue(Ecdsa.verify(c, q, hash, sig), c.name());
                assertEquals(sig, Ecdsa.sign(c, d, hash), "deterministic");
                assertFalse(Ecdsa.verify(c, q, sha("other"), sig));
                assertFalse(Ecdsa.verify(c, Ecdsa.publicKey(c, d.add(BigInteger.ONE)), hash, sig));
            }
        }
    }

    @Test
    void oursVerifiesUnderJdkAndJdkUnderOurs() throws Exception {
        Random rnd = new Random(21);
        for (int i = 0; i < 5; i++) {
            BigInteger d = new BigInteger(255, rnd).add(BigInteger.ONE);
            Point q = Ecdsa.publicKey(C, d);
            String msg = "message number " + i;
            Ecdsa.Signature sig = Ecdsa.sign(C, d, sha(msg));
            Signature v = Signature.getInstance("SHA256withECDSA");
            v.initVerify(jdkPub(q));
            v.update(msg.getBytes(StandardCharsets.UTF_8));
            assertTrue(v.verify(Der.encode(sig)), "JDK accepts our DER signature");

            Signature s = Signature.getInstance("SHA256withECDSA");
            s.initSign(jdkPriv(d));
            s.update(msg.getBytes(StandardCharsets.UTF_8));
            Ecdsa.Signature theirs = Der.decode(s.sign());
            assertTrue(Ecdsa.verify(C, q, sha(msg), theirs), "we accept JDK signature");
        }
    }

    @Test
    void verifyRejectsOutOfRangeAndTamperedValues() throws Exception {
        Point q = Ecdsa.publicKey(C, RFC_X);
        byte[] hash = sha("sample");
        Ecdsa.Signature good = Ecdsa.sign(C, RFC_X, hash);
        assertTrue(Ecdsa.verify(C, q, hash, good), "control");
        BigInteger n = C.n();
        assertFalse(Ecdsa.verify(C, q, hash, new Ecdsa.Signature(BigInteger.ZERO, good.s())));
        assertFalse(Ecdsa.verify(C, q, hash, new Ecdsa.Signature(good.r(), BigInteger.ZERO)));
        assertFalse(Ecdsa.verify(C, q, hash, new Ecdsa.Signature(good.r().add(n), good.s())), "r + n alias");
        assertFalse(Ecdsa.verify(C, q, hash, new Ecdsa.Signature(good.r(), good.s().add(n))), "s + n alias");
        assertFalse(Ecdsa.verify(C, q, hash, new Ecdsa.Signature(n, good.s())));
        assertFalse(Ecdsa.verify(C, q, hash, new Ecdsa.Signature(good.r(), n)));
        assertFalse(Ecdsa.verify(C, q, hash, new Ecdsa.Signature(good.r().negate(), good.s())));
        for (int bit = 0; bit < 256; bit += 17) {
            assertFalse(Ecdsa.verify(C, q, hash,
                new Ecdsa.Signature(good.r().flipBit(bit).mod(n), good.s())), "r bit " + bit);
            assertFalse(Ecdsa.verify(C, q, hash,
                new Ecdsa.Signature(good.r(), good.s().flipBit(bit).mod(n))), "s bit " + bit);
        }
        assertThrows(IllegalArgumentException.class,
            () -> Ecdsa.verify(C, Point.INFINITY, hash, good), "infinity key");
        assertThrows(IllegalArgumentException.class,
            () -> Ecdsa.verify(C, new Point(q.x(), q.y().add(BigInteger.ONE)), hash, good), "off-curve key");
    }

    @Test
    void highSMalleabilityAndLowS() throws Exception {
        Point q = Ecdsa.publicKey(C, RFC_X);
        byte[] hash = sha("sample");
        Ecdsa.Signature sig = Ecdsa.sign(C, RFC_X, hash);
        Ecdsa.Signature flipped = new Ecdsa.Signature(sig.r(), C.n().subtract(sig.s()));
        assertTrue(Ecdsa.verify(C, q, hash, flipped), "(r, n-s) is a second valid signature");
        BigInteger half = C.n().shiftRight(1);
        assertTrue(sig.s().compareTo(half) > 0, "RFC vector s is high: fixture for lowS");
        Ecdsa.Signature low = Ecdsa.lowS(C, sig);
        assertEquals(flipped, low);
        assertEquals(low, Ecdsa.lowS(C, low), "idempotent");
        assertTrue(Ecdsa.verify(C, q, hash, low));
        Ecdsa.Signature s2 = Ecdsa.sign(C, RFC_X, sha("test")); // s = 0x019F... is already low
        assertEquals(s2, Ecdsa.lowS(C, s2));
    }

    @Test
    void signRejectsBadPrivateKeys() throws Exception {
        byte[] hash = sha("x");
        assertThrows(IllegalArgumentException.class, () -> Ecdsa.sign(C, BigInteger.ZERO, hash));
        assertThrows(IllegalArgumentException.class, () -> Ecdsa.sign(C, C.n(), hash));
        assertThrows(IllegalArgumentException.class, () -> Ecdsa.sign(C, BigInteger.ONE.negate(), hash));
        assertNotNull(Ecdsa.sign(C, C.n().subtract(BigInteger.ONE), hash), "n-1 is the largest valid key");
        assertNotNull(Ecdsa.sign(C, BigInteger.ONE, hash), "1 is the smallest valid key");
    }

    @Test
    void longHashIsTruncatedToLeftmostBits() throws Exception {
        // 64-byte hash: only the leftmost 256 bits are used (SEC1 / RFC 6979 bits2int)
        byte[] h64 = new byte[64];
        new Random(1).nextBytes(h64);
        byte[] h32 = java.util.Arrays.copyOf(h64, 32);
        Point q = Ecdsa.publicKey(C, RFC_X);
        Ecdsa.Signature sig = Ecdsa.sign(C, RFC_X, h64);
        assertEquals(Ecdsa.sign(C, RFC_X, h32), sig);
        assertTrue(Ecdsa.verify(C, q, h32, sig));
        byte[] h8 = new byte[] {1, 2, 3, 4, 5, 6, 7, 8}; // short hash: still usable (left-padded integer)
        assertTrue(Ecdsa.verify(C, q, h8, Ecdsa.sign(C, RFC_X, h8)));
    }

    @Test
    void ecdhAgreesAndMatchesJdk() throws Exception {
        Random rnd = new Random(8);
        for (int i = 0; i < 3; i++) {
            BigInteger a = new BigInteger(255, rnd).add(BigInteger.ONE);
            BigInteger b = new BigInteger(255, rnd).add(BigInteger.ONE);
            Point qa = Ecdsa.publicKey(C, a);
            Point qb = Ecdsa.publicKey(C, b);
            byte[] s1 = Ecdh.sharedSecret(C, a, qb);
            byte[] s2 = Ecdh.sharedSecret(C, b, qa);
            assertArrayEquals(s1, s2);
            assertEquals(32, s1.length);
            KeyAgreement ka = KeyAgreement.getInstance("ECDH");
            ka.init(jdkPriv(a));
            ka.doPhase(jdkPub(qb), true);
            assertArrayEquals(ka.generateSecret(), s1, "JDK agrees");
        }
    }

    @Test
    void ecdhRejectsInvalidInputs() {
        Point q = Ecdsa.publicKey(C, BigInteger.TEN);
        assertEquals(32, Ecdh.sharedSecret(C, BigInteger.TWO, q).length, "control");
        assertThrows(IllegalArgumentException.class, () -> Ecdh.sharedSecret(C, BigInteger.ZERO, q));
        assertThrows(IllegalArgumentException.class, () -> Ecdh.sharedSecret(C, C.n(), q));
        assertThrows(IllegalArgumentException.class, () -> Ecdh.sharedSecret(C, BigInteger.TWO, Point.INFINITY));
        assertThrows(IllegalArgumentException.class,
            () -> Ecdh.sharedSecret(C, BigInteger.TWO, new Point(q.x(), q.y().subtract(BigInteger.ONE))),
            "invalid-curve point");
    }

    @Test
    void hashAtLeastNIsReducedBeforeNonceDerivation() {
        // RFC 6979 bits2octets reduces the hash mod n: hash n+1 and hash 1 give identical nonces and signatures.
        byte[] one = Curve.i2osp(BigInteger.ONE, 32);
        byte[] nPlus1 = Curve.i2osp(C.n().add(BigInteger.ONE), 32);
        assertEquals(Ecdsa.nonce(C, RFC_X, one), Ecdsa.nonce(C, RFC_X, nPlus1));
        assertEquals(Ecdsa.sign(C, RFC_X, one), Ecdsa.sign(C, RFC_X, nPlus1));
        byte[] two = Curve.i2osp(BigInteger.TWO, 32);
        assertNotEquals(Ecdsa.nonce(C, RFC_X, one), Ecdsa.nonce(C, RFC_X, two), "control: hash value matters");
    }
}

